def test_summary_values(self):
    self.assertEqual(
        summarize_counts({"apple": 2, "banana": 1, "cherry": 3}),
        {
            "min_count": 1,
            "max_count": 3,
            "median_count": 2,
            "unique_words": 3,
        },
    )

def test_summary_even_median_and_empty_input(self):
    self.assertEqual(summarize_counts({"a": 1, "b": 4}), {
        "min_count": 1,
        "max_count": 4,
        "median_count": 2.5,
        "unique_words": 2,
    })
    self.assertEqual(summarize_counts({}), {
        "min_count": None,
        "max_count": None,
        "median_count": None,
        "unique_words": 0,
    })

def test_cli_stats_option_appends_summary_object(self):
    with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8") as handle:
        handle.write("apple apple banana cherry cherry cherry")
        handle.flush()
        stdout = io.StringIO()
        with contextlib.redirect_stdout(stdout):
            self.assertEqual(main(["count", "--stats", handle.name]), 0)

